pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 v, address lg) internal {
        try c.SetMinSum(v) {} catch { return; }
        uint256 m;
        try c.MinSum() returns (uint256 __r) { m = __r; } catch { return; }
        try c.Initialized() {} catch { return; }
        bool reverted;
        try c.SetLogFile(lg) { reverted = false; } catch { reverted = true; }
        assertTrue(m == v && reverted);
    }

    function testFuzz_run(uint256 v, address lg) public {
        vm.assume(lg.code.length == 0 && uint160(lg) > 0xffff && lg != address(this) && lg != address(c) && lg != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && lg != 0x000000000000000000636F6e736F6c652e6c6f67 && lg != 0x4e59b44847b379578588920cA78FbF26c0B4956C && lg != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(v, lg);
    }

    receive() external payable {}
}
